import{_ as e,c as p,o as t,ah as S}from"./chunks/framework.BxT5r71R.js";const l=JSON.parse('{"title":"第二届BMSG FES：希望重塑日本娱乐产业","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/19_第二届BMSG FES：希望重塑日本娱乐产业.md","filePath":"zh-cn/Management2/PART2/19_第二届BMSG FES：希望重塑日本娱乐产业.md"}'),r={name:"zh-cn/Management2/PART2/19_第二届BMSG FES：希望重塑日本娱乐产业.md"};function o(n,a,_,s,M,B){return t(),p("div",null,[...a[0]||(a[0]=[S('<p>► 2023年10月</p><h2 id="第二届bmsg-fes-希望重塑日本娱乐产业" tabindex="-1">第二届BMSG FES：希望重塑日本娱乐产业 <a class="header-anchor" href="#第二届bmsg-fes-希望重塑日本娱乐产业" aria-label="Permalink to &quot;第二届BMSG FES：希望重塑日本娱乐产业&quot;">​</a></h2><p>#BMSGFES #变革 #现场演出制作</p><h3 id="我们想呈现bmsg所构想的娱乐形式-重塑日本娱乐产业" tabindex="-1">“我们想呈现BMSG所构想的娱乐形式，重塑日本娱乐产业” <a class="header-anchor" href="#我们想呈现bmsg所构想的娱乐形式-重塑日本娱乐产业" aria-label="Permalink to &quot;“我们想呈现BMSG所构想的娱乐形式，重塑日本娱乐产业”&quot;">​</a></h3><p>BMSG FES&#39;23于2023年9月23日、24日在东京的东京体育馆举行，随后于9月30日、10月1日在大阪的大阪城音乐厅举行。去年首次举办时，演出围绕BMSG成立、与Novel Core相遇、THE FIRST、BE:FIRST组建等2年来的足迹展开，将这段历程串成了一个故事。第二届又有哪些新的着力点？这次，我们先请日高谈了谈本届的主题。</p><p>去年的BMSG FES，正是为了在舞台上呼应此前的故事，为它们收束。我想，越是一路支持我们的人，就越能真切体会其中的故事，感受到演出的情感与动人之处。今年，呼应此前的故事同样是最基本的要求。不过，我们不想止步于此，还想呈现BMSG所构想的娱乐形式，重塑日本娱乐产业。</p><p>在日本，人们使用“娱乐”这个词时，似乎总是过于强调华丽的舞台效果、浓厚的虚构色彩，或是奇幻元素。</p><p>说到底，就是缺少了身体表达。我认为，娱乐本应包含更多鼓舞人、给予人力量的元素，目的在于改善人们的生活，而不是供人逃避现实。为此，需要的是人的力量。也就是说，要以高水准、高质量的表演，呈现人绽放光彩的瞬间。从创业之初起，我就在这件事上投入了很大精力。</p><p>具体来说，男子组合不应该只是完美演绎按需求打造的内容，而应该拥有自由意志，深入探索自己想表达的东西。个人艺人也是如此，我认为，他们的各种表达都必须有叙事（narrative，即从讲述者自身视角展开的故事）。因此，我们不能止步于呼应和收束此前的故事。每个人都带着自己的叙事，在此基础上，怎样用影像将其呈现得更美，又该如何更新拍摄与呈现的技术——这是本届表演者和工作人员需要共同思考的重要主题。</p><p>看过演出的人说，这很像超级碗（Super Bowl，美国职业橄榄球大联盟NFL的年度冠军赛）的中场秀。不过，与其说我们以此为目标，不如说最终的效果与它有些接近。超级碗中场秀的舞台制作始终以音乐为中心，BMSG FES也重视音乐本身，所以两者的方向确实相同。日本的娱乐往往容易忽略这一点，或许正因如此，大家才觉得耳目一新，进而联想到超级碗。我自己也深感，这件事值得投入。</p><h3 id="为什么不断探索影像的可能性" tabindex="-1">为什么不断探索影像的可能性 <a class="header-anchor" href="#为什么不断探索影像的可能性" aria-label="Permalink to &quot;为什么不断探索影像的可能性&quot;">​</a></h3><p><strong>如前所述，影像是本届重点投入的领域之一。从旗下艺人的MV（音乐视频）到D.U.N.K.等企划，都能看出BMSG对影像的重视。日高表示：“今后也必须不断提升影像质量。”</strong></p><p>K-POP为什么能在世界各地拥有粉丝？高质量的影像是重要原因之一。反过来说，也正因为跨越国界传播离不开影像，其质量才逐渐发展出独到之处。我觉得，日本如果也想走向全球，就应该把提升影像质量视为理所当然的事。</p><p>这次演出主要在2个方面下了功夫。一是把灯光等元素也考虑进去，讲究镜头中的画面效果；二是着力做好舞台上的稳定器（gimbal，用于视频拍摄的防抖装置）拍摄。我们在D.U.N.K.中尝试了多种无人机拍摄方式，这次也采用了，但尤其花心思的还是稳定器拍摄。我觉得，不只是通过影院或线上观看演出的人，即使是现场观众，看稳定器拍摄的画面，也比直接用肉眼观看更有临场感。而且，影像质量越高，就越能衬托出艺人歌唱、舞蹈时最本真的瞬间。</p><p><strong>从舞台后方近距离观看各位艺人的表演时，他们一边唱歌、一边与摄影师沟通的样子，也令人印象深刻。</strong></p><p>调动摄影团队的积极性很重要。否则，我们这边就得提出更多要求，调整起来也很费力。听说不少现场确实充斥着吼叫和斥骂，但我很重视营造轻松的氛围，大家不必用那种方式沟通，而是可以坦诚地交换意见。彩排时，一位来现场观摩学习的年轻摄影师也参与了拍摄。我比较在意别人的感受，所以一边观察他的反应，一边提出各种要求。结果，他的表情像是在说“再多来一点”，于是我就接连提要求（笑）。彩排中也出了几次差错，但大家都很积极，说声“再来一次”就继续。他的眼睛始终闪闪发亮。于是，之后所有正式演出的场次，我都请他来拍了。</p><p>能这样沟通而不闹得不愉快，一方面与我的性格有关，另一方面，我想，BMSG才成立几年、旗下艺人又多是年轻新人，这些也有帮助。另外，大家都很愿意投入精力做出好作品。我一直很珍视“大人的文化祭”这个说法，能在这样的氛围里一起做事，也很重要。（编者注：文化祭是日本学校举办的文化活动，通常由学生共同筹办。这里借指成年人齐心协力、投入创作的氛围。）这也是我可以自豪地说自己的管理取得了成效的地方。</p><p><strong>会场顶部，BMSG EAST队所在的舞台上手一侧悬挂着巨大的太阳装饰，BMSG WEST队所在的下手一侧则悬挂着月亮装饰。（编者注：日本舞台术语中，“上手”指观众面向舞台时的右侧，“下手”指左侧。）影像中还出现了类似日全食的画面。划分BMSG EAST与BMSG WEST两队，以及两队各自的歌曲、MV等内容背后，究竟隐藏着怎样的主题？</strong></p><p>这些设定不一定非要传达给观众，但制作时，我们确实构想了一个背景。人们分别住在太阳国和月国这2个世界里，各自生活，从不相遇。不过，每隔60年，就会有一天，月亮与太阳同时升起。只有这时，两国居民才会相逢，并举办盛大的庆典。BMSG EAST队和BMSG WEST队，就像分别代表太阳国与月国，在一处类似古罗马竞技场的地方参加对抗赛。不过，与其说是争斗，不如说更接近J联赛或NBA的全明星赛。</p><p>我们在与现场演出团队开会时分享这些设定，再由大家推进具体工作。随着团队经验不断积累，非得我参与才能推进的事情也越来越少，现在确实省了不少心。</p><p>另外，最近一位能力很强的工作人员以创意总监（creative director）的身份正式加入BMSG，这也发挥了很大作用。上届演出时，我希望观众在散场回去的路上，仍能感受到演出的世界观，所以用投影仪在墙上投射相关影像，还挂起了灯笼。他协助完成了这些工作，我们就是这样开始合作的。当时只是请他作为外部工作人员帮忙，但演出结束后，他对我说：“我得到了启示。我觉得自己应该更多地投入BMSG的工作，有什么能帮忙的吗？”于是，我试着交给他一些事，结果常常感叹：“原来创意总监还能做到这些！”在创意工作上，我感觉自己亲手处理的次数减半了，能参与的环节却增加了一倍。</p><p>这次想到太阳国和月国的设定，也是从与他的交谈中延伸出来的。我把设定讲给他听，他就会问：“两国居民多少年相逢一次？”“那是怎样的庆典？”这样一问，许多细节就逐渐明确了，他还会在此基础上拓展构想。讲完设定，第二天他就能拿出初步草图，方便我们对照各自的想象、统一画面构思，这一点也很值得感谢。</p><h3 id="_2023年的成果-为今后增添信心" tabindex="-1">2023年的成果，为今后增添信心 <a class="header-anchor" href="#_2023年的成果-为今后增添信心" aria-label="Permalink to &quot;2023年的成果，为今后增添信心&quot;">​</a></h3><p><strong>演出持续了约5个小时，却感觉转瞬即逝。衔接流畅的曲目编排，似乎也是原因之一。</strong></p><p>演出比计划更长，是因为艺人们真正站上舞台后，似乎都有很多话想说。这当然是件开心的事，不过简单算一下，23人每人多说2分钟，就会延长46分钟（笑）。</p><p>编排演出曲目时，我重视的同样是叙事，另外就是衔接要流畅。Core和Shota（Aile The Shota）的部分分别交给他们自己负责，只在开头和结尾做些调整，尽量与前后环节无缝衔接。我们还有很多有意思的合作歌曲，所以我想，这种流畅衔接的方式，今后应该还会不断发展。</p><p><strong>现在谈这个或许有些早，不过，今年的BMSG FES已经取得了令人满意的成果，那么明年及以后，日高打算以怎样的形式举办呢？</strong></p><p>上一次，此前2年的工作一直以这场演出为念。只要从创业到那时走的路没有错，无论怎样呈现，都会打动人心；而且，我们相当于为这个企划投入了2年。但这次不只是把原先构想的故事变成现实，还要把当下正在发生的故事呈现在舞台上，这一点很不容易。即便如此，我们还是做出了那样的水准，我也松了一口气。这应该会成为我们今后一段时期的优势。心里想着：“好，这样每年都能办下去了！”</p><p>明年要办成什么样呢？其实已经有了具体的企划，敬请期待。BMSG FES不能依赖某个特定团队的号召力，而要形成旗下各方粉丝共同参与的局面。所以，即便公司获得了足够的信任，有资格使用巨蛋场馆，现在似乎也还不是举办巨蛋规模演出的时候。明明是自家公司举办的活动，却有艺人觉得场馆规模超出了自己的观众号召力，我认为这就不是一种健康的状态。</p><p>我确实希望更多人能来看，所以即使仍在体育馆规模的场地举行，也不妨把演出压缩得十分紧凑，一天举办日间、晚间两场。比如，以只有在BMSG FES才能看到的合作表演为主，每位艺人自己的原创歌曲只安排1至2首，连续演出2小时左右，中间不停顿。整场始终保持高潮，节奏也很明快，或许还不错。</p><p>当然，今后如果各方面的承载能力有所提升，BMSG FES本身的举办方式也可能随之改变。但至少明年，我还是想延续现在这种“大家一起参与”的家族演唱会形式。</p>',31)])])}const h=e(r,[["render",o]]);export{l as __pageData,h as default};
